```go
func ParseSince(s string, now time.Time) (time.Time, error) {
	if t, err := time.Parse(time.RFC3339, s); err == nil {
		return t, nil
	}
	if strings.HasPrefix(s, "+") {
		return time.Time{}, fmt.Errorf("--since %q: a log has no future", s)
	}
	d, err := time.ParseDuration(strings.TrimPrefix(s, "-"))
	if err != nil {
		return time.Time{}, fmt.Errorf("--since %q: not a time or a duration", s)
	}
	return now.Add(-d), nil
}
```

`now` is a parameter so the test never has to wait for a clock.

